  'ai.title': 'Asistente',
  'tour.home.ask.title': 'El asistente',
  'tour.home.ask.text': 'Este botón está arriba en todas las pantallas. Escríbele o háblale para registrar un gasto, preguntar si te alcanza o saber cómo vas con tus gastos y tus deudas.',
  'tour.goal.3.title': 'Lo que te convendría aportar este mes',
  'tour.goal.3.text': 'No es una cuota fija. Con fecha, es lo que le falta a la meta repartido en los meses que quedan; sin fecha, tu promedio de los últimos 3 meses.',
  'tour.assistant.1.title': 'Registra o pregunta con tus palabras',
  'tour.assistant.1.text': 'Escribe «gasté 45 mil en almuerzo» o «¿me alcanza para unos tenis de 300 mil?». Todo se calcula en tu celular, sin internet.',
  'tour.assistant.2.title': 'Escribe o habla',
  'tour.assistant.2.text': 'Toca el micrófono para dictar con la voz de tu celular. Nada se guarda sin que toques Guardar.',
  'tour.assistant.3.title': 'Aprende de tus respuestas',
  'tour.assistant.3.text': 'Lo que no entienda te lo pregunta una vez, con botones. Y si cambias la cuenta, el producto o la categoría antes de guardar, la próxima vez que lo digas igual lo trae así.',
  'tour.assistant.4.title': 'Pregunta por tu mes y tus deudas',
  'tour.assistant.6.title': 'Más preguntas sobre tu dinero',
  'tour.assistant.6.text': 'Prueba «¿qué pago cada mes?» para ver tus pagos fijos y lo que gastas todos los meses, «¿cuánto me han dado mis cuentas?» para tus intereses, «¿por qué gasté más?», o pregunta por un tope o una meta por su nombre: «¿cómo va la meta del viaje?».',
  'tour.assistant.5.title': 'Tu conversación y tus preguntas',
  'tour.assistant.5.text': 'La conversación se guarda en tu celular los días que elijas, hasta 60: toca «Cambiar», debajo del título del asistente. Las flechas de la derecha te llevan al principio o al final de la conversación. Registrar movimientos aquí es siempre gratis; sin Finance Pro tienes 20 preguntas gratis cada mes.',
  'tour.assistant.4.text': 'Prueba «¿cómo voy este mes?», «¿en qué gasté más?», «¿cuánto debo?», «¿qué deuda pago primero?» o «¿qué pagos tengo este mes?». Te responde con tus cifras y te dice por qué.',
