  'cards.bank.same': 'Coincide con lo que calcula la app.',
  'cards.bank.cutDay': "La diferencia es justo lo que registraste el día del corte ({count} compras del {date}): el banco las cobró después y van en tu próxima factura.",
  'cards.bank.cutDay.one': "La diferencia es justo lo que registraste el día del corte (1 compra del {date}): el banco la cobró después y va en tu próxima factura.",
  'cards.bank.change': 'Cambiar',
  'cards.bank.reset': 'Volver a lo calculado',
  'cards.bank.ask.title': '¿Tu extracto dice otra cifra?',
  'cards.bank.ask.body': "Escribe el pago total que aparece en tu extracto. La app lo usará para esta factura y te mostrará la diferencia.",
  'cards.bank.ask.action': 'Escribir la del extracto',
  'cards.bank.hintCutDay': "Registraste {count} compras el día del corte ({amount}). Si el banco las cobró después, tu extracto mostrará menos y aparecerán en la próxima factura.",
  'cards.bank.hintCutDay.one': "Registraste 1 compra el día del corte ({amount}). Si el banco la cobró después, tu extracto mostrará menos y aparecerá en la próxima factura.",
  'cards.bank.sheet.title': 'Cifra de tu extracto',
  'cards.bank.sheet.label': 'Pago total del corte del {date}',
  'cards.bank.sheet.hint': "Escribe el \"pago total\" (o \"saldo a pagar\") del extracto: es lo que debes pagar para no generar intereses. No es el \"pago mínimo\". Solo cambia esta factura: tus movimientos no cambian y el próximo corte se calcula solo.",
  'cards.bank.sheet.save': 'Usar esta cifra',
  'cards.why.link': '¿Por qué el banco puede decir otra cifra?',
  'cards.why.title': '¿Por qué tu extracto y la app pueden decir cifras distintas?',
  'cards.why.intro': "La app calcula la factura con los movimientos que registras y con la fecha que tú les pones. El banco usa la fecha en que le llega cada cobro, y agrega cobros que la app no conoce. Por eso a veces no coinciden, aunque nada esté mal.",
  'cards.why.cutDay.title': 'Compras del día del corte',
  'cards.why.cutDay.body': "Una compra hecha el día del corte, o la noche anterior, puede llegarle al banco uno o dos días después. El banco la pone en la factura siguiente; la app, en la de la fecha que tú le diste.",
  'cards.why.pending.title': 'Compras que el banco aún no aplica',
  'cards.why.pending.body': "Apps de transporte, domicilios, hoteles o gasolineras a veces primero reservan un valor y lo cobran días después, incluso por otro monto. Mientras el banco no lo cobre, no aparece en su factura.",
  'cards.why.payments.title': 'Pagos que tardan en aplicarse',
  'cards.why.payments.body': "Un pago hecho de noche, en fin de semana, en festivo o desde otro banco puede aplicarse el siguiente día hábil y quedar después del corte.",
  'cards.why.fees.title': 'Cobros que solo conoce el banco',
  'cards.why.fees.body': "Intereses, cuota de manejo, seguros, 4x1000 (el impuesto a los movimientos), comisiones o avances. Si no los registras, la app no los cuenta.",
  'cards.why.installments.title': 'Compras a cuotas',
  'cards.why.installments.body': "Si pagas una compra a cuotas, el banco cobra solo la cuota del mes y sus intereses. La app cuenta la compra completa el día en que la hiciste.",
  'cards.why.foreign.title': 'Compras en otra moneda',
  'cards.why.foreign.body': "El banco convierte las compras en otra moneda con la tasa de cambio del día en que las cobra, que puede ser distinta a la del día de la compra.",
  'cards.why.refunds.title': 'Devoluciones y reversos',
  'cards.why.refunds.body': "Una devolución puede tardar días o semanas en llegar y quedar en otra factura.",
  'cards.why.typed.title': 'Algo registrado distinto',
  'cards.why.typed.body': "Una compra olvidada, repetida, con otro valor o con otra fecha. Si comparas el extracto línea por línea con tus movimientos, lo encuentras.",
  'cards.why.minimum.title': 'Pago mínimo y pago total',
  'cards.why.minimum.body': "El pago mínimo es lo menos que puedes pagar para no atrasarte, pero lo que quede sin pagar genera intereses. Para no pagar intereses tienes que hacer el pago total. Si no tienes compras a cuotas, los dos suelen ser iguales; si las tienes, el mínimo es menor. La app muestra el pago total.",
  'cards.why.what.title': 'Qué hacer',
  'cards.why.what.body': "Si tu extracto dice otra cifra, escríbela en \"¿Tu extracto dice otra cifra?\". La app la usará para esta factura, te mostrará la diferencia y pasará a \"Desde el corte\" lo que el banco dejó para después.",
  'cards.why.close': 'Entendido',
