  'ai.title': 'Assistant',
  'tour.home.ask.title': 'The assistant',
  'tour.home.ask.text': 'This button is at the top of every screen. Type or speak to record a spending, ask whether you can afford something or see how your spending and your debts are going.',
  'tour.goal.3.title': 'What it would suit you to put in this month',
  'tour.goal.3.text': 'It is not a fixed instalment. With a date, it is what the goal lacks spread over the months left; without one, your average of the last 3 months.',
  'tour.assistant.1.title': 'Record or ask in your own words',
  'tour.assistant.1.text': 'Write “I spent 45 thousand on lunch” or “can I afford trainers for 300 thousand?”. Everything is worked out on your phone, with no internet.',
  'tour.assistant.2.title': 'Type or speak',
  'tour.assistant.2.text': 'Tap the microphone to dictate with your phone’s voice typing. Nothing is saved until you tap Save.',
  'tour.assistant.3.title': 'It learns from your answers',
  'tour.assistant.3.text': 'What it does not understand it asks you once, with buttons. And if you change the account, the product or the category before saving, the next time you say it the same way it comes like that.',
  'tour.assistant.6.title': 'More questions about your money',
  'tour.assistant.6.text': 'Try “what do I pay every month?” for your fixed payments and what you spend every month, “how much have my accounts paid me?” for your interest, “why did I spend more?”, or ask about a cap or a goal by its name: “how is the trip goal going?”.',
  'tour.assistant.5.title': 'Your conversation and your questions',
  'tour.assistant.5.text': 'The conversation is kept on your phone for the days you choose, up to 60: tap “Change”, under the title of the assistant. The arrows on the right take you to the start or the end of the conversation. Registering movements here is always free; without Finance Pro you get 20 free questions every month.',
  'tour.assistant.4.title': 'Ask about your month and your debts',
  'tour.assistant.4.text': 'Try “how is this month going?”, “what did I spend most on?”, “how much do I owe?”, “which debt should I pay first?” or “what payments do I have this month?”. It answers with your figures and says why.',
