  'tour.assistant.8.title': 'What you record most, in one tap',
  'tour.assistant.8.text': 'The bulb starts with what you record most: a transfer between your products, a usual expense. One tap opens the form ready with the accounts, products, category and note. You only type the amount and save. Press and hold one to pin it on top.',
