  'cards.statementOf.bank': 'Statement of {date} · as your bank states it',
  'cards.bank.title': 'Using the figure on your statement',
  'cards.bank.computed': 'From your movements, the app works out {amount}.',
  'cards.bank.diffLess': 'Your statement says {diff} less.',
  'cards.bank.diffMore': 'Your statement says {diff} more.',
  'cards.bank.same': 'It matches what the app works out.',
  'cards.bank.cutDay': 'The difference is exactly what you recorded on the cut-off day ({count} purchases on {date}): the bank posted them later and they go on your next statement.',
  'cards.bank.cutDay.one': 'The difference is exactly what you recorded on the cut-off day (1 purchase on {date}): the bank posted it later and it goes on your next statement.',
  'cards.bank.change': 'Change',
  'cards.bank.reset': 'Back to the app\'s figure',
  'cards.bank.ask.title': 'Does your statement say something else?',
  'cards.bank.ask.body': 'Type the total due on your statement. The app will use it for this statement and show you the difference.',
  'cards.bank.ask.action': 'Type the statement\'s figure',
  'cards.bank.hintCutDay': 'You recorded {count} purchases on the cut-off day ({amount}). If the bank posted them later, your statement will say less and they will come on the next one.',
  'cards.bank.hintCutDay.one': 'You recorded 1 purchase on the cut-off day ({amount}). If the bank posted it later, your statement will say less and it will come on the next one.',
  'cards.bank.sheet.title': 'Your statement\'s figure',
  'cards.bank.sheet.label': 'Total due at the cut-off of {date}',
  'cards.bank.sheet.hint': 'Type the statement\'s "total due" (or "balance to pay"): it is what you pay to be charged no interest. If your statement also shows a different "minimum payment", it is not that one. It only changes this statement: your movements stay as they are, and the next cut-off is worked out again by itself.',
  'cards.bank.sheet.save': 'Use this figure',
  'cards.why.link': 'Why can the bank say something else?',
  'cards.why.title': 'Why can your statement and the app differ?',
  'cards.why.intro': 'The app works the statement out from the movements you record, with the date you give them. The bank uses the date each movement reaches it, and charges the app does not know about. So they sometimes differ, with nothing wrong.',
  'cards.why.cutDay.title': 'Purchases on the cut-off day',
  'cards.why.cutDay.body': 'A purchase made on the cut-off day, or the night before, can reach the bank a day or two later. The bank puts it on the next statement; the app, on the one of the date you gave it.',
  'cards.why.pending.title': 'Purchases the bank has not posted yet',
  'cards.why.pending.body': 'Ride apps, deliveries, hotels or fuel sometimes hold an amount first and charge it days later, even for a different figure. Until the bank posts it, it is not on its statement.',
  'cards.why.payments.title': 'Payments that take time to post',
  'cards.why.payments.body': 'A payment made at night, on a weekend or holiday, or from another bank can post on the next working day and fall after the cut-off.',
  'cards.why.fees.title': 'Charges only the bank knows',
  'cards.why.fees.body': 'Interest, the card fee, insurance, the 4x1000 tax, commissions or cash advances. Unless you record them as movements, the app does not count them.',
  'cards.why.installments.title': 'Purchases in installments',
  'cards.why.installments.body': 'If you spread a purchase over installments, the bank bills only the month\'s installment and its interest. The app counts it whole on the day of the purchase.',
  'cards.why.foreign.title': 'Purchases in another currency',
  'cards.why.foreign.body': 'The bank converts them at the rate of the day it posts them, which may differ from the rate on the day of the purchase.',
  'cards.why.refunds.title': 'Refunds and reversals',
  'cards.why.refunds.body': 'A refund can take days or weeks to arrive and land on another statement.',
  'cards.why.typed.title': 'Something recorded differently',
  'cards.why.typed.body': 'A purchase forgotten, entered twice, with another amount or another date. Comparing the statement line by line with your movements shows it.',
  'cards.why.minimum.title': 'Minimum payment and total due',
  'cards.why.minimum.body': 'The minimum payment is the least you can pay without falling behind or having the card blocked, but whatever stays unpaid does earn interest. What avoids interest is the total due. Without installment purchases the two are usually the same figure; with them, the minimum is lower (only this month\'s installment) and the rest stays in installments with its interest. The app shows the total due.',
  'cards.why.what.title': 'What to do',
  'cards.why.what.body': 'If your statement says something else, type it in "Does your statement say something else?". The app will use it for this statement, show you the difference and move to "Since the cut-off" what the bank left for later.',
  'cards.why.close': 'Got it',
